import unittest
from candidate import iscube

class TestIsCube(unittest.TestCase):
    def test_zero(self):
        self.assertTrue(iscube(0))

    def test_positive_cubes(self):
        for n in [1, 8, 27, 64, 125, 1000]:
            self.assertTrue(iscube(n))

    def test_negative_cubes(self):
        for n in [-1, -8, -27, -64, -125, -1000]:
            self.assertTrue(iscube(n))

    def test_non_cubes_small(self):
        for n in [2, 3, 5, 6, 7, 9, 10, 11, 12, 13]:
            self.assertFalse(iscube(n))

    def test_non_cubes_medium(self):
        for n in [100, 101, 200, 999, 1001, 1234, 1235]:
            self.assertFalse(iscube(n))

    def test_boundary_large_cube(self):
        large = 1000 ** 3
        self.assertTrue(iscube(large))
        self.assertTrue(iscube(-large))

    def test_float_input_cube(self):
        self.assertTrue(iscube(8.0))
        self.assertTrue(iscube(-8.0))

    def test_float_input_non_cube(self):
        self.assertFalse(iscube(8.5))
        self.assertFalse(iscube(-8.5))

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            iscube(None)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            iscube("8")

    def test_complex_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            iscube(complex(2, 3))

    def test_boolean_true_as_one(self):
        self.assertTrue(iscube(True))

    def test_boolean_false_as_zero(self):
        self.assertTrue(iscube(False))

    def test_consistency_across_calls(self):
        for n in [0, 1, 8, 27, -27, 1000, -1000]:
            result1 = iscube(n)
            result2 = iscube(n)
            self.assertEqual(result1, result2)

    def test_rounding_edge_case(self):
        # 27 is 3**3, but floating point may produce 2.999999... which rounds to 3
        self.assertTrue(iscube(27))
        self.assertFalse(iscube(26))

    def test_large_negative_cube(self):
        large_neg = -(-1000) ** 3
        self.assertTrue(iscube(large_neg))

if __name__ == "__main__":
    unittest.main()
